  using System;
  using System.ComponentModel;
  using System.Runtime.InteropServices;

  public static class Dpapi
  {
      [StructLayout(LayoutKind.Sequential)]
      private struct DATA_BLOB
      {
          public int cbData;
          public IntPtr pbData;
      }

      [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Auto)]
      [return: MarshalAs(UnmanagedType.Bool)]
      private static extern bool CryptUnprotectData(
          ref DATA_BLOB pDataIn,
          IntPtr ppszDataDescr,
          ref DATA_BLOB pOptionalEntropy,
          IntPtr pvReserved,
          IntPtr pPromptStruct,
          int dwFlags,
          out DATA_BLOB pDataOut);

      [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Auto)]
      [return: MarshalAs(UnmanagedType.Bool)]
      private static extern bool CryptUnprotectData(
          ref DATA_BLOB pDataIn,
          IntPtr ppszDataDescr,
          IntPtr pOptionalEntropy,
          IntPtr pvReserved,
          IntPtr pPromptStruct,
          int dwFlags,
          out DATA_BLOB pDataOut);

      [DllImport("kernel32.dll", SetLastError = true)]
      private static extern IntPtr LocalFree(IntPtr hMem);

      private const int CRYPTPROTECT_UI_FORBIDDEN = 0x1;

      public static byte[] Unprotect(byte[] encrypted, byte[] optionalEntropy = null)
      {
          if (encrypted == null || encrypted.Length == 0)
              throw new ArgumentException("encrypted empty");

          DATA_BLOB inBlob = new DATA_BLOB();
          DATA_BLOB outBlob = new DATA_BLOB();
          IntPtr pIn = IntPtr.Zero;
          IntPtr pEnt = IntPtr.Zero;

          try
          {
              pIn = Marshal.AllocHGlobal(encrypted.Length);
              Marshal.Copy(encrypted, 0, pIn, encrypted.Length);
              inBlob.cbData = encrypted.Length;
              inBlob.pbData = pIn;

              bool ok;
              if (optionalEntropy != null && optionalEntropy.Length > 0)
              {
                  pEnt = Marshal.AllocHGlobal(optionalEntropy.Length);
                  Marshal.Copy(optionalEntropy, 0, pEnt, optionalEntropy.Length);
                  DATA_BLOB entBlob = new DATA_BLOB();
                  entBlob.cbData = optionalEntropy.Length;
                  entBlob.pbData = pEnt;
                  ok = CryptUnprotectData(ref inBlob, IntPtr.Zero, ref entBlob, IntPtr.Zero, IntPtr.Zero, CRYPTPROTECT_UI_FORBIDDEN, out outBlob);
              }
              else
              {
                  ok = CryptUnprotectData(ref inBlob, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, CRYPTPROTECT_UI_FORBIDDEN, out outBlob);
              }

              if (!ok)
                  throw new Win32Exception(Marshal.GetLastWin32Error());

              byte[] result = new byte[outBlob.cbData];
              Marshal.Copy(outBlob.pbData, result, 0, outBlob.cbData);
              return result;
          }
          finally
          {
              if (pIn != IntPtr.Zero)
                  Marshal.FreeHGlobal(pIn);
              if (pEnt != IntPtr.Zero)
                  Marshal.FreeHGlobal(pEnt);
              if (outBlob.pbData != IntPtr.Zero)
                  LocalFree(outBlob.pbData);
          }
      }
  }

