  import json, time, random, urllib.request, urllib.error

  def post_json(endpoint, payload, token, timeout=10, max_req=1_000_000, max_resp=5_000_000, retries=4, base=0.5):
      if not endpoint.startswith("https://"):
          raise ValueError("HTTPS only")
      body = json.dumps(payload).encode()
      if len(body) > max_req:
          raise ValueError(f"req {len(body)} > {max_req}")
      headers = {
          "Content-Type": "application/json",
          "Content-Length": str(len(body)),
          "Authorization": f"Bearer {token}",
      }
      last_err = None
      for i in range(retries + 1):
          try:
              req = urllib.request.Request(endpoint, data=body, headers=headers, method="POST")
              with urllib.request.urlopen(req, timeout=timeout) as r:
                  data = r.read(max_resp + 1)
                  if len(data) > max_resp:
                      raise ValueError(f"resp {len(data)} > {max_resp}")
                  ct = r.headers.get("Content-Type", "")
                  return r.status, json.loads(data) if "json" in ct else data
          except urllib.error.HTTPError as e:
              last_err = e
              if 400 <= e.code < 500 and e.code not in (408, 429):
                  raise
          except Exception as e:
              last_err = e
          if i < retries:
              time.sleep(base * (2 ** i) + random.uniform(0, 0.2))
      raise last_err

  usage:
